import { lastAttempt } from "./invoices.js";

const HOUR = 60 * 60 * 1000;

// ASSUMPTION: the repo does not spell out finance's schedule. Each entry is the wait after the
// invoice's previous attempt before scheduled retry n+1 is due; once used up the invoice stays failed.
export const RETRY_DELAYS_MS = [24 * HOUR, 72 * HOUR, 120 * HOUR];

/**
 * Scheduled retries of failed invoices: at most one gateway call per invoice per run, and only when
 * due. Paid, declined and open invoices are untouched. The retry reuses the key of the last attempt,
 * since a timeout may hide a charge that went through; the provider then returns it instead of
 * charging again. Returns the invoices that were retried.
 */
export async function retryFailedInvoices(invoices, gateway, now = new Date(), { delaysMs = RETRY_DELAYS_MS } = {}) {
  const retried = [];
  for (const invoice of invoices) {
    if (invoice.status !== "failed") continue;
    const last = lastAttempt(invoice);
    if (!last) continue;
    const done = invoice.scheduledRetries ?? 0;
    if (done >= delaysMs.length) continue;
    if (now.getTime() < new Date(last.at).getTime() + delaysMs[done]) continue;

    invoice.scheduledRetries = done + 1;
    retried.push(invoice);
    const at = now.toISOString();
    try {
      const result = await gateway.charge({ customer: invoice.customer, amountCents: invoice.amountCents, idempotencyKey: last.key });
      invoice.attempts.push({ at, key: last.key, outcome: result.status });
      if (result.status === "succeeded") {
        invoice.status = "paid";
        invoice.chargeId = result.id;
      } else {
        invoice.status = "declined";
      }
    } catch (err) {
      invoice.attempts.push({ at, key: last.key, outcome: err.code ?? "error" });
    }
  }
  return retried;
}
