import { test } from "node:test";
import assert from "node:assert/strict";
import { chargeInvoice } from "../src/billing.js";
import { Gateway } from "../src/gateway.js";
import { openInvoice } from "../src/invoices.js";
import { retryFailedInvoices } from "../src/retries.js";

const sub = { id: "sub_t", customer: "cus_test", priceCents: 4900, active: true };
const T0 = new Date("2026-10-01T06:00:00Z");
const DAY = 24 * 3600 * 1000;
const later = (ms) => new Date(T0.getTime() + ms);

async function failedInvoice(script) {
  const gw = new Gateway({ script });
  const inv = await chargeInvoice(openInvoice(sub, "2026-10"), gw, { now: T0 });
  assert.equal(inv.status, "failed");
  return { gw, inv };
}

test("a failed invoice is not retried before it is due", async () => {
  const { gw, inv } = await failedInvoice(["unavailable", "unavailable", "unavailable"]);
  const calls = gw.calls;
  assert.deepEqual(await retryFailedInvoices([inv], gw, later(DAY - 1)), []);
  assert.equal(gw.calls, calls);
});

test("a due retry pays the invoice", async () => {
  const { gw, inv } = await failedInvoice(["unavailable", "unavailable", "unavailable"]);
  await retryFailedInvoices([inv], gw, later(DAY));
  assert.equal(inv.status, "paid");
  assert.equal(gw.chargesFor(sub.customer).length, 1);
});

test("a retry after timeouts recovers the hidden charge instead of double charging", async () => {
  const { gw, inv } = await failedInvoice(["timeout", "timeout", "timeout"]);
  assert.equal(gw.chargesFor(sub.customer).length, 1);
  await retryFailedInvoices([inv], gw, later(DAY));
  assert.equal(inv.status, "paid");
  assert.equal(gw.chargesFor(sub.customer).length, 1);
  assert.equal(inv.chargeId, gw.charges[0].id);
});

test("at most one retry per invoice per run, and the next waits for its own delay", async () => {
  const { gw, inv } = await failedInvoice(["unavailable", "unavailable", "unavailable", "unavailable"]);
  const calls = gw.calls;
  await retryFailedInvoices([inv], gw, later(DAY));
  assert.equal(gw.calls, calls + 1);
  assert.equal(inv.status, "failed");
  await retryFailedInvoices([inv], gw, later(DAY + 1000));
  assert.equal(gw.calls, calls + 1);
  await retryFailedInvoices([inv], gw, later(DAY + 3 * DAY));
  assert.equal(gw.calls, calls + 2);
});

test("retries stop once the schedule is used up", async () => {
  const { gw, inv } = await failedInvoice(Array(20).fill("unavailable"));
  for (let i = 1; i <= 6; i++) await retryFailedInvoices([inv], gw, later(i * 30 * DAY));
  assert.equal(inv.scheduledRetries, 3);
  assert.equal(inv.status, "failed");
});

test("paid, declined and open invoices are left alone", async () => {
  const gw = new Gateway();
  const mk = (status) => ({ ...openInvoice(sub, "2026-10"), status, attempts: [{ at: T0.toISOString(), key: "k", outcome: "x" }] });
  const invs = [mk("paid"), mk("declined"), mk("open")];
  assert.deepEqual(await retryFailedInvoices(invs, gw, later(30 * DAY)), []);
  assert.equal(gw.calls, 0);
  assert.deepEqual(invs.map((i) => i.status), ["paid", "declined", "open"]);
});

test("a decline on retry is final", async () => {
  const { gw, inv } = await failedInvoice(["unavailable", "unavailable", "unavailable", "declined"]);
  await retryFailedInvoices([inv], gw, later(DAY));
  assert.equal(inv.status, "declined");
  const calls = gw.calls;
  await retryFailedInvoices([inv], gw, later(30 * DAY));
  assert.equal(gw.calls, calls);
});
